package com.bank.statement;

import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;
import org.apache.kafka.common.errors.RecordTooLargeException;
import java.util.*;
import java.util.logging.*;

public class StatementPublisherDemo {
    private static final Logger log = Logger.getLogger(StatementPublisherDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // A big statement for Priya (CUR3001): simulate ~3 MB of JSON text.
        String bigStatement = buildBigStatement("CUR3001", 3_000_000);

        // ---- Attempt 1: DEFAULT limits — this throws RecordTooLargeException ----
        Properties defaults = baseProps();
        try (Producer<String, String> p = new KafkaProducer<>(defaults)) {
            p.send(new ProducerRecord<>("statements", "CUR3001", bigStatement)).get();
        } catch (RecordTooLargeException e) {
            log.severe("Rejected at default 1 MB limit: " + e.getMessage());
        } catch (Exception e) {
            // get() wraps the cause; unwrap for clarity
            if (e.getCause() instanceof RecordTooLargeException)
                log.severe("Rejected at default 1 MB limit (wrapped): " + e.getCause().getMessage());
            else log.log(Level.SEVERE, "Publish failed", e);
        }

        // ---- Attempt 2: raise producer limit + compression ----
        Properties raised = baseProps();
        raised.put(ProducerConfig.MAX_REQUEST_SIZE_CONFIG, 5_242_880);
        raised.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, "zstd");
        try (Producer<String, String> p = new KafkaProducer<>(raised)) {
            RecordMetadata meta = p.send(
                new ProducerRecord<>("statements", "CUR3001", bigStatement)).get();
            log.info(() -> "Large statement published (compressed) offset " + meta.offset());
        } catch (Exception e) {
            log.log(Level.SEVERE, "Publish failed", e);
        }

        // ---- Attempt 3: claim-check pattern — publish only a reference ----
        // In reality we upload the PDF to S3 first, then publish the pointer.
        StatementReference ref = new StatementReference(
            "CUR3001", "s3://bank-statements/CUR3001/2026-10.pdf", 3_000_000, "sha256:abc123");
        try (Producer<String, String> p = new KafkaProducer<>(baseProps())) {
            RecordMetadata meta = p.send(
                new ProducerRecord<>("statements", "CUR3001", ref.toJson())).get();
            log.info(() -> "Claim-check reference published (tiny) offset " + meta.offset());
        } catch (Exception e) {
            log.log(Level.SEVERE, "Reference publish failed", e);
        }
    }

    private static Properties baseProps() {
        Properties p = new Properties();
        p.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        p.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        p.put(ProducerConfig.ACKS_CONFIG, "all");
        return p;
    }

    private static String buildBigStatement(String account, int approxBytes) {
        StringBuilder sb = new StringBuilder(approxBytes + 64);
        sb.append("{\"account\":\"").append(account).append("\",\"lines\":[");
        while (sb.length() < approxBytes) {
            sb.append("{\"desc\":\"RENT CREDIT\",\"amount\":50000},");
        }
        sb.append("]}");
        return sb.toString();
    }
}

