class StatementReference {
    private final String account;
    private final String blobUri;
    private final long sizeBytes;
    private final String checksum;
    StatementReference(String account, String blobUri, long sizeBytes, String checksum) {
        this.account = account; this.blobUri = blobUri;
        this.sizeBytes = sizeBytes; this.checksum = checksum;
    }
    String toJson() {
        return "{\"account\":\"" + account + "\",\"blobUri\":\"" + blobUri
             + "\",\"size\":" + sizeBytes + ",\"checksum\":\"" + checksum + "\"}";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
